-- Reviewed-by: Claude (agent, #226)
-- Hand edits (#26 part 1, docs/engineering/database.md "Audit tables", tenancy.md):
--   * app_uuid_v7() before the tables: time-ordered ids (Postgres 17 has no uuidv7()).
--   * tenantPolicy() for audit_event and ai_call. audit_event.workspace_id is null for account-level
--     events: ws_isolation never matches them, so they are written only by app_audit_append() and
--     read by their actor through account_self while no workspace is pinned.
--   * Append-only: the app role keeps SELECT and INSERT; UPDATE, DELETE and TRUNCATE are revoked,
--     and app_audit_immutable() rejects them for every role (the owner included) unless the
--     transaction-local app.audit_retention is 'on', which only the purge functions set.
--   * app_audit_append(): the only writer of audit_event. Under an advisory lock per workspace
--     chain (a fixed key for account-level events) it reads the chain's latest hash as prev_hash and
--     stores hash = sha256(prev_hash || app_audit_canonical(event)::text). Canonical JSON is the
--     jsonb text form (sorted keys) of every column except prev_hash and hash.
--   * app_purge_audit() / app_purge_ai_calls(): the retention path, refusing cutoffs younger than
--     180 days (CERT-In). owner_definer_* policies back the SECURITY DEFINER functions under FORCE RLS.
CREATE TYPE "public"."audit_actor_kind" AS ENUM('user', 'staff', 'system', 'api');--> statement-breakpoint
CREATE TYPE "public"."audit_outcome" AS ENUM('success', 'denied', 'error');--> statement-breakpoint
CREATE FUNCTION app_uuid_v7() RETURNS uuid
  LANGUAGE sql VOLATILE PARALLEL SAFE
  AS $$
    SELECT encode(
      set_bit(
        set_bit(
          overlay(uuid_send(gen_random_uuid())
                  PLACING substring(int8send(floor(extract(epoch FROM clock_timestamp()) * 1000)::bigint) FROM 3)
                  FROM 1 FOR 6),
          52, 1),
        53, 1),
      'hex')::uuid
  $$;--> statement-breakpoint
