-- Rejects UPDATE, DELETE and TRUNCATE for every role; DELETE and TRUNCATE pass only while the
-- retention path has set app.audit_retention for the transaction.
CREATE FUNCTION app_audit_immutable() RETURNS trigger
  LANGUAGE plpgsql SET search_path = public, pg_temp
  AS $$
    BEGIN
      IF TG_OP IN ('DELETE', 'TRUNCATE')
         AND current_setting('app.audit_retention', true) = 'on' THEN
        RETURN OLD;
      END IF;
      RAISE EXCEPTION '% is append-only: % is not allowed', TG_TABLE_NAME, TG_OP
        USING ERRCODE = 'insufficient_privilege';
    END
  $$;--> statement-breakpoint
CREATE TRIGGER "audit_event_immutable" BEFORE UPDATE OR DELETE ON "audit_event"
  FOR EACH ROW EXECUTE FUNCTION app_audit_immutable();--> statement-breakpoint
CREATE TRIGGER "audit_event_no_truncate" BEFORE TRUNCATE ON "audit_event"
  FOR EACH STATEMENT EXECUTE FUNCTION app_audit_immutable();--> statement-breakpoint
CREATE TRIGGER "ai_call_immutable" BEFORE UPDATE OR DELETE ON "ai_call"
  FOR EACH ROW EXECUTE FUNCTION app_audit_immutable();--> statement-breakpoint
CREATE TRIGGER "ai_call_no_truncate" BEFORE TRUNCATE ON "ai_call"
  FOR EACH STATEMENT EXECUTE FUNCTION app_audit_immutable();--> statement-breakpoint
-- The canonical JSON an event's hash covers: every column except prev_hash and hash, as jsonb
-- (keys sorted by jsonb), with created_at in UTC to the microsecond. verifyChain (#227) reuses it.
CREATE FUNCTION app_audit_canonical(e audit_event) RETURNS jsonb
  LANGUAGE sql STABLE PARALLEL SAFE SET search_path = public, pg_temp
  AS $$
    SELECT jsonb_build_object(
      'id', e.id,
      'workspace_id', e.workspace_id,
      'actor_user_id', e.actor_user_id,
      'actor_kind', e.actor_kind,
      'action', e.action,
      'target_kind', e.target_kind,
      'target_id', e.target_id,
      'outcome', e.outcome,
      'ip', host(e.ip),
      'user_agent_hash', e.user_agent_hash,
      'request_id', e.request_id,
      'metadata', e.metadata,
      'created_at', to_char(e.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
    )
  $$;--> statement-breakpoint
-- The only writer of audit_event. A workspace event must be for the caller's pinned workspace; a
-- null workspace is an account-level event on the account chain.
CREATE FUNCTION app_audit_append(
    p_workspace_id uuid,
    p_actor_user_id uuid,
    p_actor_kind audit_actor_kind,
    p_action text,
    p_target_kind text DEFAULT NULL,
    p_target_id text DEFAULT NULL,
    p_outcome audit_outcome DEFAULT 'success',
    p_ip inet DEFAULT NULL,
    p_user_agent_hash text DEFAULT NULL,
    p_request_id text DEFAULT NULL,
    p_metadata jsonb DEFAULT '{}'::jsonb
  ) RETURNS TABLE (id uuid, hash bytea)
  LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    #variable_conflict use_column
    DECLARE
      e audit_event;
    BEGIN
      IF p_workspace_id IS NOT NULL AND p_workspace_id IS DISTINCT FROM app_current_workspace() THEN
        RAISE EXCEPTION 'audit event for a workspace other than the pinned one'
          USING ERRCODE = 'insufficient_privilege';
      END IF;
      PERFORM pg_advisory_xact_lock(
        hashtextextended('audit_event:' || coalesce(p_workspace_id::text, 'account'), 0));
      SELECT a.hash INTO e.prev_hash FROM audit_event a
      WHERE a.workspace_id IS NOT DISTINCT FROM p_workspace_id
      ORDER BY a.created_at DESC, a.id DESC
      LIMIT 1;
      e.id := app_uuid_v7();
      e.workspace_id := p_workspace_id;
      e.actor_user_id := p_actor_user_id;
      e.actor_kind := p_actor_kind;
      e.action := p_action;
      e.target_kind := p_target_kind;
      e.target_id := p_target_id;
      e.outcome := coalesce(p_outcome, 'success');
      e.ip := p_ip;
      e.user_agent_hash := p_user_agent_hash;
      e.request_id := p_request_id;
      e.metadata := coalesce(p_metadata, '{}'::jsonb);
      -- Taken after the lock, so created_at follows chain order.
      e.created_at := clock_timestamp();
      e.hash := sha256(coalesce(e.prev_hash, ''::bytea)
                       || convert_to(app_audit_canonical(e)::text, 'UTF8'));
      INSERT INTO audit_event SELECT (e).*;
      RETURN QUERY SELECT e.id, e.hash;
    END
  $$;--> statement-breakpoint
-- Retention path: delete audit events older than `cutoff`, never younger than 180 days.
CREATE FUNCTION app_purge_audit(cutoff timestamptz) RETURNS bigint
  LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    DECLARE
      n bigint;
    BEGIN
      IF cutoff IS NULL OR cutoff > now() - interval '180 days' THEN
        RAISE EXCEPTION 'audit retention must keep at least 180 days'
          USING ERRCODE = 'invalid_parameter_value';
      END IF;
      PERFORM set_config('app.audit_retention', 'on', true);
      DELETE FROM audit_event a WHERE a.created_at < cutoff;
      GET DIAGNOSTICS n = ROW_COUNT;
      PERFORM set_config('app.audit_retention', '', true);
      RETURN n;
    END
  $$;--> statement-breakpoint
-- Retention path: delete ai_call rows older than `cutoff`, never younger than 180 days.
CREATE FUNCTION app_purge_ai_calls(cutoff timestamptz) RETURNS bigint
  LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    DECLARE
      n bigint;
    BEGIN
      IF cutoff IS NULL OR cutoff > now() - interval '180 days' THEN
        RAISE EXCEPTION 'ai_call retention must keep at least 180 days'
          USING ERRCODE = 'invalid_parameter_value';
      END IF;
      PERFORM set_config('app.audit_retention', 'on', true);
      DELETE FROM ai_call c WHERE c.created_at < cutoff;
      GET DIAGNOSTICS n = ROW_COUNT;
      PERFORM set_config('app.audit_retention', '', true);
      RETURN n;
    END
  $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_uuid_v7(), app_audit_immutable(), app_audit_canonical(audit_event),
  app_audit_append(uuid, uuid, audit_actor_kind, text, text, text, audit_outcome, inet, text, text, jsonb),
  app_purge_audit(timestamptz), app_purge_ai_calls(timestamptz) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_uuid_v7(), app_audit_canonical(audit_event),
  app_audit_append(uuid, uuid, audit_actor_kind, text, text, text, audit_outcome, inet, text, text, jsonb),
  app_purge_audit(timestamptz), app_purge_ai_calls(timestamptz) TO causedeck_app;
